CREATE TABLE t1(a,b,c); CREATE TABLE t2(d,e,"big f"); INSERT INTO t1 VALUES(1,2,3),(4,8,456),(4,0,20456); INSERT INTO t2 VALUES(4,5,20456); CREATE UNIQUE INDEX t2d ON t2(d); CREATE TRIGGER tr1 AFTER INSERT ON t1 BEGIN INSERT INTO t2 VALUES(new.a,new.b,new.c) ON CONFLICT(d) DO UPDATE SET "big f"=excluded."big f"; END;